 p.get_by_role('button',name='Cancel settings',exact=True).click();p.evaluate('follow126.home()');p.get_by_role('button',name='Meal groups for Tuesday',exact=True).first.click();d=p.get_by_role('dialog',name='Choose Tuesday’s meal groups',exact=True);d.get_by_role('checkbox',name='Potatoes',exact=True).check();d.get_by_role('button',name='Save meal groups',exact=True).click();p.wait_for_timeout(200);assert p.evaluate('serving126.assignments().Tuesday')==['Rice'];assert next(e for e in p.evaluate('follow126.next()')if e['id'] in [10,11])['cat']=='Potatoes'
 # Explicit unchecked carry advances the sequence but preserves the recipe and scale.
 p.evaluate('serving126.scaleMain()');p.wait_for_timeout(200);p.evaluate('phone126.carryState();phone126.start()');advance=p.get_by_role('dialog',name='Start next week',exact=True);advance.locator('.start-week-choice input').first.uncheck();advance.get_by_role('button',name='Start next week →',exact=True).click();p.wait_for_timeout(150);assert p.evaluate('follow126.current()[0].id')==2;assert p.evaluate('follow126.current()[0].cat')=='Potatoes';assert p.evaluate('serving126.currentScale()')==2;assert any(s['checked'] and 'carry rice' in s['text'] for s in p.evaluate('phone126.sources("current")'));assert p.evaluate('phone126.manual()[0].text')=='7 cartons oat milk';p.evaluate('follow126.undo()');assert p.evaluate('follow126.current()[0].cat')=='Rice';p.evaluate('follow126.redo()');assert p.evaluate('follow126.current()[0].cat')=='Potatoes';assert p.evaluate('serving126.currentScale()')==2
 # Grouped same-name headers remain exact dated occurrences. Cross-view checks and wording share one store.
 p.evaluate('follow126.seed();serving126.pendingRecipe();phone126.groceries()');p.get_by_role('switch',name='Group by meal',exact=True).check();sections=p.locator('.grocery-meal-section');assert sections.count()==2;first=sections.first;first.locator('.grocery-checkbox-target input').first.check();checked=p.evaluate('phone126.sources("both")');assert sum(s['checked'] for s in checked)==1;p.get_by_role('switch',name='Group by meal',exact=True).uncheck();assert p.locator('.master-grocery-item').filter(has=p.locator('.grocery-ingredient-name',has_text='rice')).first.locator('.grocery-checkbox-target input').evaluate('(x)=>x.indeterminate');p.get_by_role('switch',name='Group by meal',exact=True).check()
 p.get_by_role('button',name='Collapse all groceries',exact=True).click();assert not first.locator('.master-grocery-item').first.is_visible();p.get_by_role('button',name='Expand all groceries',exact=True).click();first.locator('.grocery-contribution-edit').first.click();d=p.get_by_role('dialog',name='Edit grocery item',exact=True);d.get_by_role('textbox',name='Grocery item',exact=True).fill('1 cup fragrant rice');d.get_by_role('button',name='Save grocery item',exact=True).click();sources=p.evaluate('phone126.sources("both")');assert sum('fragrant' in s['text'] for s in sources)==1
 p.get_by_role('switch',name='Group by meal',exact=True).uncheck();rice=p.locator('.master-grocery-item').filter(has=p.locator('.grocery-ingredient-name',has_text='rice')).first;assert rice.locator('.grocery-checkbox-target input').first.is_checked() # Wording separates this aggregate, without checking future source.
