 p.set_viewport_size({'width':360,'height':800});p.evaluate('phone126.sizes("normal");follow126.home(1)');p.locator('.preview-plan-card').first.locator('.meal-actions-toggle').click();base.base.shot(p,name,'next-parity');p.evaluate('follow126.home();phone126.tasks()');assert 'Cook everything' not in p.locator('#todaysTodo').inner_text();base.base.shot(p,name,'todo-spacing')
 # Read-only diagnostic includes actual plan anchors, IDs/provenance and task due dates, no writes.
 diag=p.evaluate('phone126.diagnostic()');assert diag['unchanged'];assert diag['d']['plans'][0]['currentAnchor']=='2026-11-17';assert diag['d']['tasks'];assert diag['d']['queues'];b=p.evaluate('follow126.backup()');p.evaluate('b=>phone126.restore(b)',b);p.reload();assert p.evaluate('follow126.backup()');assert not errors,errors
 if prefix:assert p.evaluate('localStorage.getItem("mealRotationDataV1")')=='WORKING SENTINEL'
 c.close();print('PASS',name,'follow126 unified editor, other-copy protection, both recurring entry points/carry-scale, grouped exact sources/checks/wording/reload, popup Back/keyboard/thumbs, inline Back/large text, due spacing/read-only diagnostic/backup',flush=True)
